<h2>Calculate PCR master mix volumes</h2><p class="lead">Scale common PCR components across reactions with an overage allowance and concentration-based primer calculation.</p><div class="notice">Thermo Fisher examples scale non-template PCR components for multiple reactions and use C1V1=C2V2 for primer/probe concentration. This tool does not prescribe assay chemistry.</div><div class="form-grid"><div class="field"><label for="rxn">Number of reactions</label><input id="rxn" type="number" value="24" min="1" step="1"></div><div class="field"><label for="over">Extra volume / overage (%)</label><input id="over" type="number" value="10" min="0" step="any"></div><div class="field"><label for="total">Final reaction volume (µL)</label><input id="total" type="number" value="20" min="0.001" step="any"></div><div class="field"><label for="mm">2× master mix per reaction (µL)</label><input id="mm" type="number" value="10" min="0" step="any"></div><div class="field"><label for="stock">Primer stock concentration (µM)</label><input id="stock" type="number" value="10" min="0.000001" step="any"></div><div class="field"><label for="finalp">Final concentration of each primer (µM)</label><input id="finalp" type="number" value="0.5" min="0" step="any"></div><div class="field"><label for="template">Template per reaction (µL; excluded from master mix)</label><input id="template" type="number" value="2" min="0" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Effective batch reactions</span><strong id="batch">—</strong></div><div class="metric"><span>Each primer / reaction</span><strong id="primer">—</strong></div><div class="metric"><span>Water / reaction</span><strong id="water">—</strong></div><div class="metric"><span>Master-mix cocktail volume</span><strong id="master">—</strong></div></div><div class="table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>Component</th><th>Per reaction</th><th>Batch volume</th></tr></thead><tbody id="mixRows"></tbody></table></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('batch').textContent='—';$('primer').textContent='—';$('water').textContent='—';$('master').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const n=Math.floor(num('rxn')),ov=num('over')/100,t=num('total'),mm=num('mm'),stock=num('stock'),fp=num('finalp'),templ=num('template');if(!(n>=1&&ov>=0&&t>0&&mm>=0&&stock>0&&fp>=0&&templ>=0))throw 0;const p=fp*t/stock,water=t-mm-2*p-templ;if(water<0)throw 0;const mult=n*(1+ov),cocktail=(mm+2*p+water)*mult;$('batch').textContent=fmt(mult,2)+' reaction-equivalents';$('primer').textContent=fmt(p,4)+' µL';$('water').textContent=fmt(water,4)+' µL';$('master').textContent=fmt(cocktail,3)+' µL';$('mixRows').innerHTML=[['2× master mix',mm,mm*mult],['Forward primer',p,p*mult],['Reverse primer',p,p*mult],['Water',water,water*mult],['Template (add separately)',templ,templ*n]].map(x=>'<tr><td>'+x[0]+'</td><td>'+fmt(x[1],4)+' µL</td><td>'+fmt(x[2],3)+' µL</td></tr>').join('');$('note').textContent='Primer volume uses C1V1=C2V2. Template is excluded from the shared cocktail to support sample-specific addition; follow your validated assay protocol.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
